<script setup lang="ts">
import { computed, inject, onBeforeUnmount, onMounted, ref, watch, type Ref } from 'vue';
import { onBeforeRouteLeave, useRoute } from 'vue-router';
import { displayTime, downloadFile, errorMessage, hours, statusLabel, today } from '@worktime/api-client';
import { reporting, type Capabilities, type ExportJob, type Report } from '../../shared/reporting';
const route=useRoute();
const props=defineProps<{section:string}>();const kind=ref(props.section==='workload'?'workload':props.section==='onsite'?'onsite':'project-costs'),busy=ref(false),error=ref(''),notice=ref(''),caps=ref<Capabilities>(),report=ref<Report>(),exports=ref<ExportJob[]>([]);
const loadedQuery=ref('');
const from=ref(today().slice(0,7)+'-01'),to=ref(today()),mode=ref('CURRENT'),versionIds=ref(''),userId=ref(''),workItemId=ref(''),departmentId=ref(''),level=ref(''),grain=ref('WEEK');
const sharedBusy=inject<Ref<boolean>>('operationBusy');watch(busy,v=>{if(sharedBusy)sharedBusy.value=v;});
const title=computed(()=>props.section==='workload'?'人员负荷与履约':props.section==='onsite'?'现场台账与占比':'项目投入与成本');
const labels:Record<string,string>={employeeNo:'工号',name:'姓名 / 名称',departmentName:'部门',levelCode:'职级',periodStart:'期间起日',periodEnd:'期间末日',requiredMinutes:'应填小时',confirmedWorkMinutes:'确认实际工作',confirmedProjectMinutes:'项目工作',confirmedNonProjectMinutes:'非项目工作',confirmedIdleMinutes:'待分配',leaveMinutes:'请假',overtimeMinutes:'超额工作',reportedMinutes:'已填写',missingDays:'缺填天数',pendingCount:'未决项',loadPercent:'工作负荷',complete:'审批完整',status:'统计状态',expectedPersonDays:'应填人日',readyOnTimeDays:'按时完成人日',unresolvedCount:'未决项',timelyRatePercent:'填报及时率',lateSubmitPeople:'逾期提交人数',notSubmittedPeople:'未提交人数',approvalSubmitted:'应处理审批项',approvalHandled:'已处理审批项',approvalApproved:'通过项',approvalRejected:'驳回项',approvalCompletionPercent:'审批完成率',overduePackages:'超期审批包',code:'对象编码',type:'对象类型',pmName:'项目负责人',confirmedMinutes:'确认小时',onsiteDays:'现场天数',laborCost:'标准人工成本',onsiteCost:'标准现场成本',totalCost:'标准总成本',participants:'参与人数',date:'日期',workItemName:'归集对象',reason:'事由',state:'流程状态',projectMinutes:'本项目实际工作',totalWorkMinutes:'当日实际工作',ratioPercent:'项目投入占比',ratioStatus:'占比状态',reviewRequired:'需核实',oaStatus:'OA 核对',oaComparedAt:'核对时间',oaNote:'来源说明',kind:'记录类型',recordId:'记录 ID',revisionId:'版本 ID',action:'动作',minutes:'小时',content:'工作内容',approvedAt:'确认时间',approvedByName:'实际审批人',costAmount:'确认金额',dailyRate:'日标准',policyVersion:'计价规则',onsitePeople:'现场人数',confirmedDays:'确认天数',ratioNumeratorMinutes:'合格项目小时',ratioDenominatorMinutes:'合格实际小时',people:'人员数',reviewCount:'建议核实天数'};
const tableFields:Record<string,string[]>={workload:['name','employeeNo','departmentName','levelCode','periodStart','periodEnd','requiredMinutes','confirmedWorkMinutes','confirmedProjectMinutes','confirmedNonProjectMinutes','confirmedIdleMinutes','leaveMinutes','overtimeMinutes','reportedMinutes','missingDays','pendingCount','loadPercent','status'],compliance:['name','employeeNo','expectedPersonDays','readyOnTimeDays','missingDays','unresolvedCount'],'project-costs':['code','name','departmentName','pmName','confirmedMinutes','onsiteDays','laborCost','onsiteCost','totalCost','participants','pendingCount'],onsite:['date','name','employeeNo','workItemName','reason','state','onsiteDays','onsiteCost','projectMinutes','totalWorkMinutes','ratioPercent','ratioStatus','reviewRequired','oaStatus','oaComparedAt','oaNote'],details:['date','name','employeeNo','departmentName','workItemName','kind','action','state','minutes','content','reason','approvedAt','approvedByName','costAmount','dailyRate','levelCode','policyVersion','recordId','revisionId']};
const columns=computed(()=>report.value?(tableFields[kind.value]??[]).filter(k=>report.value!.rows.some(r=>r[k]!==undefined)):[]);
function format(key:string,value:unknown){if(value===null||value===undefined)return 'N/A';if(['laborCost','onsiteCost','totalCost','costAmount','dailyRate'].includes(key))return `¥${value}`;if(typeof value==='boolean')return value?'是':'否';if(key.endsWith('Minutes')||key==='minutes')return `${hours(Number(value))}h`;if(key.endsWith('Percent'))return `${value}%`;if(['generatedAt','oaComparedAt','approvedAt'].includes(key))return displayTime(String(value));if(typeof value==='object')return JSON.stringify(value);const dict:Record<string,string>={JUNIOR:'初级',MIDDLE:'中级',SENIOR:'高级',CONFIRMED:'已确认',INCOMPLETE:'待完善',NO_BASE:'无基数',NOT_APPLICABLE:'N/A',NOT_COMPARED:'尚未核对',DATA_PENDING:'资料待完善',OA_NO_RECORD:'OA 无对应记录',NOT_REPORTED:'OA 已批待申报',UNKNOWN:'覆盖未知',MATCHED:'匹配',MISMATCH:'不匹配',NO_ORDER:'无单',OA_ONLY:'OA 已批待核实',TIME:'工时',ONSITE:'现场日',PROJECT:'项目',NON_PROJECT:'非项目',IDLE:'待分配',REPORT:'申报'};return dict[String(value)]??statusLabel(String(value));}
function query(){return {from:from.value,to:to.value,mode:mode.value,versionIds:mode.value==='FORMAL'?versionIds.value:'',userId:userId.value,workItemId:workItemId.value,departmentId:departmentId.value,level:level.value,grain:grain.value};}
async function load(){if(busy.value)return;busy.value=true;error.value='';try{report.value=await reporting.report(kind.value,query());loadedQuery.value=JSON.stringify(query());}catch(e){report.value=undefined;error.value=errorMessage(e);}finally{busy.value=false;}}
async function loadExports(){try{exports.value=await reporting.exports();}catch(e){error.value=errorMessage(e);}}
async function createExport(){busy.value=true;error.value='';try{const q=query();const filtered=Object.fromEntries(Object.entries(q).filter(([,value])=>value));const job=await reporting.export({...filtered,kind:kind.value,versionIds:q.versionIds?q.versionIds.split(',').map(v=>v.trim()):undefined});notice.value=`导出任务 ${job.id} 已登记，文件生成后可下载。`;await loadExports();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function download(job:ExportJob){busy.value=true;error.value='';try{downloadFile(await reporting.download(job.id),`${title.value}-${job.id}.xlsx`);}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
function color(row:Record<string,unknown>){if(kind.value!=='workload'||row.status!=='CONFIRMED'||row.loadPercent==null)return '';const value=Number(row.loadPercent);return value<80?'load-low':value<=110?'load-normal':value<=130?'load-high':'load-red';}
async function changeKind(value:string){kind.value=value;await load();}
onMounted(async()=>{if(route.query.version&&route.query.month){const m=String(route.query.month);from.value=m+'-01';to.value=new Date(Date.UTC(Number(m.slice(0,4)),Number(m.slice(5)),0)).toISOString().slice(0,10);mode.value='FORMAL';versionIds.value=String(route.query.version);}try{caps.value=await reporting.capabilities();await load();await loadExports();}catch(e){error.value=errorMessage(e);}});onBeforeRouteLeave(()=>!busy.value);onBeforeUnmount(()=>{if(sharedBusy)sharedBusy.value=false;});
</script>
<template><div class="workflow-page"><div class="workflow-head"><div><h1>{{ title }}</h1><p>当前数据按最新有效版本统计；正式月报来自已发布的固定快照。</p></div></div><nav class="workflow-tabs"><template v-if="section==='workload'"><button :class="{active:kind==='workload'}" :disabled="busy" @click="changeKind('workload')">工作负荷</button><button :class="{active:kind==='compliance'}" :disabled="busy" @click="changeKind('compliance')">填报与审批履约</button></template><template v-else-if="section==='costs'"><button :class="{active:kind==='project-costs'}" :disabled="busy" @click="changeKind('project-costs')">项目汇总</button><button :class="{active:kind==='details'}" :disabled="busy" @click="changeKind('details')">记录与计价明细</button></template></nav><form class="workflow-filters" @submit.prevent="load"><label>开始日期<input v-model="from" required type="date" :disabled="busy" /></label><label>结束日期<input v-model="to" required type="date" :disabled="busy" /></label><label>统计口径<select aria-label="统计口径" v-model="mode" :disabled="busy"><option value="CURRENT">当前确认数据</option><option value="FORMAL">正式月报快照</option></select></label><label v-if="mode==='FORMAL'">正式版本 ID<input v-model="versionIds" placeholder="留空取每月最新版；多个用逗号" :disabled="busy" /></label><label>人员<select aria-label="人员" v-model="userId" :disabled="busy"><option value="">可见人员</option><option v-for="u in caps?.users" :key="u.id" :value="u.id">{{ u.name }} / {{ u.employeeNo }}</option></select></label><label>项目<select aria-label="项目" v-model="workItemId" :disabled="busy"><option value="">可见项目</option><option v-for="w in caps?.projects" :key="w.id" :value="w.id">{{ w.name }}</option></select></label><label>部门<select aria-label="部门" v-model="departmentId" :disabled="busy"><option value="">可见部门</option><option v-for="d in caps?.departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><label v-if="kind==='workload'">粒度<select aria-label="粒度" v-model="grain" :disabled="busy"><option value="WEEK">自然周</option><option value="DAY">每日</option></select></label><button class="primary" :disabled="busy">{{ busy?'正在读取…':'查询' }}</button></form><p v-if="error" class="workflow-error" role="alert">{{ error }}</p><p v-if="notice" class="workflow-success">{{ notice }}</p><template v-if="report"><p class="workflow-note">{{ report.mode==='FORMAL'?'正式快照':'当前数据' }} · {{ report.from }} 至 {{ report.to }} · 生成于 {{ displayTime(report.generatedAt) }}</p><p v-if="report.missingMonths.length" class="workflow-warning">以下月份尚无正式版本：{{ report.missingMonths.join('、') }}。这些月份未混入当前数据。</p><p v-if="report.versions.length">采用版本：{{ report.versions.map(v=>`${v.month} V${v.versionNo}（ID ${v.id}）`).join('，') }}</p><div class="workflow-metrics"><div v-for="(value,key) in report.summary" :key="key"><span>{{ labels[key]??key }}</span><strong>{{ format(key,value) }}</strong></div></div><p v-if="kind==='workload'" class="workflow-note">仅审批完整且有基数时显示负荷色阶：低于 80%、80% 至 110%、110% 至 130%、高于 130%；待完善数据保持中性。</p><p v-if="kind==='compliance'" class="workflow-note">及时率分母为应填人日；审批完成包含通过与驳回，两类分别列示。</p><p v-if="kind==='onsite'" class="workflow-note">投入占比仅在当日完整确认且实际工作大于 0 时计算。低于 50% 仅提示核实；OA 来源未知不会视为无出差单。</p><section class="workflow-panel"><div class="workflow-between"><h2>{{ report.rows.length }} 条可见记录</h2><button :disabled="busy||loadedQuery!==JSON.stringify(query())" @click="createExport">申请 Excel 导出</button></div><div v-if="!report.rows.length" class="workflow-empty">当前条件没有可见数据。</div><div v-else class="workflow-table-wrap"><table class="workflow-table"><thead><tr><th v-for="column in columns" :key="column" :data-field="column">{{ labels[column] }}</th></tr></thead><tbody><tr v-for="(row,index) in report.rows" :key="index"><td v-for="column in columns" :key="column" :data-field="column" :class="column==='loadPercent'?color(row):''">{{ format(column,row[column]) }}</td></tr></tbody></table></div></section><details v-if="report.details.length"><summary>超时与未决明细 {{ report.details.length }} 条</summary><article v-for="(row,index) in report.details" :key="index" class="workflow-panel"><span v-for="(value,key) in row" :key="key">{{ labels[key]??key }}：{{ format(key,value) }}　</span></article></details></template><section class="workflow-panel"><div class="workflow-between"><h2>我的导出任务</h2><button :disabled="busy" @click="loadExports">刷新任务</button></div><p class="workflow-note">异步生成，不显示估算进度。下载时再次校验当前权限。</p><p v-if="!exports.length">暂无导出任务。</p><div v-for="job in exports" :key="job.id" class="workflow-between export-row"><span>任务 {{ job.id }} · {{ ({QUEUED:'排队中',RUNNING:'生成中',SUCCEEDED:'已生成',FAILED:'失败'} as Record<string,string>)[job.state]??job.state }} · {{ displayTime(job.createdAt) }}<small v-if="job.error"> {{ job.error }}</small></span><button v-if="job.state==='SUCCEEDED'" :disabled="busy" @click="download(job)">下载 XLSX</button></div></section></div></template>
<style scoped>
.export-row { padding: var(--ts-space-12) 0; border-bottom: 1px solid var(--ts-color-divider); }
.load-low { background: var(--ts-color-primary-soft); color: var(--ts-color-primary-text); }
.load-normal { background: var(--ts-color-success-soft); color: var(--ts-color-success); }
.load-high { background: var(--ts-color-warning-soft); color: var(--ts-color-warning); }
.load-red { background: var(--ts-color-danger-soft); color: var(--ts-color-danger); }
.workflow-table :is(th, td):is([data-field$="Minutes"], [data-field$="Cost"], [data-field$="Percent"], [data-field$="Count"], [data-field$="Days"], [data-field="minutes"], [data-field="costAmount"], [data-field="dailyRate"], [data-field="participants"]) { text-align: right; white-space: nowrap; }
</style>
